class JobRepository implements Repository<
  TenantEntity & {
    queueName: string;
    state: string;
    job: Job<unknown>;
    leaseUntil?: number;
    error?: string;
  }
> {
  private readonly values = new Map<
    string,
    TenantEntity & {
      queueName: string;
      state: string;
      job: Job<unknown>;
      leaseUntil?: number;
      error?: string;
    }
  >();
  findById(tenantId: string, id: string) {
    return Promise.resolve(this.values.get(`${tenantId}:${id}`));
  }
  list(
    tenantId: string,
    page: PageRequest,
  ): Promise<
    Page<
      TenantEntity & {
        queueName: string;
        state: string;
        job: Job<unknown>;
        leaseUntil?: number;
        error?: string;
      }
    >
  > {
    const values = [...this.values.values()]
      .filter((item) => item.tenantId === tenantId)
      .sort((a, b) => a.id.localeCompare(b.id));
    const start =
      page.cursor === undefined ? 0 : values.findIndex((item) => item.id === page.cursor) + 1;
    const items = values.slice(start, start + page.limit);
    const last = items.at(-1);
    return Promise.resolve({
      items,
      ...(start + page.limit < values.length && last !== undefined ? { nextCursor: last.id } : {}),
    });
  }
  insert(
    entity: TenantEntity & {
      queueName: string;
      state: string;
      job: Job<unknown>;
      leaseUntil?: number;
      error?: string;
    },
  ) {
    this.values.set(`${entity.tenantId}:${entity.id}`, entity);
    return Promise.resolve(entity);
  }
  update(
    entity: TenantEntity & {
      queueName: string;
      state: string;
      job: Job<unknown>;
      leaseUntil?: number;
      error?: string;
    },
    expectedVersion: number,
  ) {
    const current = this.values.get(`${entity.tenantId}:${entity.id}`);
    if (current?.version !== expectedVersion) return Promise.reject(new Error('conflict'));
    this.values.set(`${entity.tenantId}:${entity.id}`, entity);
    return Promise.resolve(entity);
  }
  delete(): Promise<boolean> {
    return Promise.resolve(false);
  }
}
